import subprocess,json
sql="""BEGIN READ ONLY; SET LOCAL statement_timeout='25s'; select day,status,count(*),count(distinct question) from monitor_runs where model_id='deepseek' and day between '2026-10-16' and '2026-10-30' group by day,status order by day; select s.production_valid,count(*) from monitor_sources s join monitor_runs r using(model_id,run_id) where r.model_id='deepseek' and r.day between '2026-10-16' and '2026-10-30' group by s.production_valid; select jsonb_object_keys(payload) from monitor_runs where model_id='deepseek' order by day desc limit 30; COMMIT;"""
r=subprocess.run(['docker','exec','monitor-postgres','sh','-c','psql -U "$POSTGRES_USER" -d "$POSTGRES_DB" -At -c "$1"','sh',sql],capture_output=True,text=True,timeout=35);print(r.stdout);print(r.stderr);assert r.returncode==0
